pm.test("Confirm results are within the valid date range" , function(){
    var dateRange = pm.response.json();
    var minDate = new Date(dateRange.dates.minimum);
    var maxDate = new Date(dateRange.dates.maximum);
    for (var i = 0; i < dateRange.results.length; i++) {
        var releaseDate = new Date(dateRange.results[i].release_date);
        pm.expect(releaseDate).to.be.at.greaterThan(minDate);
        pm.expect(releaseDate).to.be.at.lessThan(maxDate);
    }
});

